/**
 * TimelineService — LCTS Phase 10.
 *
 * Builds a ChangeTimeline by composing:
 *  1. Structural history from graphify-out/memory-intel.json (migrations + decisions).
 *     CONNECTED — the artifact is generated by `pnpm graph:memory` and is always up to date
 *     when the developer runs the standard graph refresh pipeline.
 *  2. Injected LiveFacts from adapters (commits / PRs / deployments / CI runs).
 *     CONNECTED only when facts are provided; NOT_CONNECTED otherwise, with the exact
 *     env-var sources listed per feed so operators know what to wire.
 *
 * READ ONLY. DETERMINISTIC. NO Date.now()/new Date(). NO network. NO FS write.
 * Injectable clock: constructor(core, now) — default is `defaultNow` from the shared envelope.
 */
import { type Evidence, type LcisEngine, evidence, notConnected } from '@letbuyy/lcis-core';
import type { LiveFact } from '@letbuyy/lcis-adapters';
import { z } from 'zod';
import {
  defaultNow,
  tracking,
  type ChangeKind,
  type ChangeRecord,
  type ChangeTimeline,
} from '../shared/index';

// ── Memory-intel artifact schema (loose — unknown fields are ignored) ───────────

/** A single decision entry as it appears in memory-intel.json. */
const RawDecisionSchema = z
  .object({
    id: z.string(),
    type: z.string().optional(),
    source: z.string().optional(),
    section: z.string().optional(),
    rule: z.string().optional(),
  })
  .loose();

/** A single migration entry as it appears in memory-intel.json. */
const RawMigrationSchema = z
  .object({
    n: z.number(),
    file: z.string().optional(),
    name: z.string().optional(),
    type: z.string().optional(),
    decision: z.string().optional(),
  })
  .loose();

/** Top-level memory-intel.json shape. */
const MemoryIntelSchema = z
  .object({
    decisions: z.array(RawDecisionSchema).optional(),
    migrations: z.array(RawMigrationSchema).optional(),
    summary: z.object({}).loose().optional(),
  })
  .loose();

type RawDecision = z.infer<typeof RawDecisionSchema>;
type RawMigration = z.infer<typeof RawMigrationSchema>;

// ── Live-fact kind mapping ─────────────────────────────────────────────────────

/**
 * Explicit mapping from LiveFact.kind to ChangeKind.
 * Anything not in this map → 'infra' (honest catch-all; never fabricated).
 */
const FACT_KIND_MAP: Readonly<Record<string, ChangeKind>> = {
  deployment: 'deployment',
  pr: 'pr',
  'ci-run': 'commit',
  release: 'deployment',
};

function factKind(raw: string): ChangeKind {
  return FACT_KIND_MAP[raw] ?? 'infra';
}

// ── Not-connected live feeds (when zero liveFacts are provided) ───────────────

const NOT_CONNECTED_FEEDS = [
  {
    feed: 'repo.events',
    source: 'github adapter (GITHUB_TOKEN, GITHUB_REPOSITORY)',
  },
  {
    feed: 'ci.workflows',
    source: 'github-actions adapter',
  },
  {
    feed: 'deploy.vercel',
    source: 'vercel adapter (VERCEL_TOKEN)',
  },
] as const;

// ── Decision cap ──────────────────────────────────────────────────────────────

const DECISION_CAP = 50;

// ── TimelineService ───────────────────────────────────────────────────────────

export class TimelineService {
  constructor(
    private readonly core: LcisEngine,
    private readonly now: () => string = defaultNow,
  ) {}

  /**
   * Build a ChangeTimeline.
   *
   * - Reads memory-intel.json (zod-loose; malformed/absent → honest empty + notConnected evidence).
   * - Maps migrations → ChangeRecord (kind='migration', action='applied', at=null — honest).
   * - Maps decisions → ChangeRecord (kind='decision', action='observed', at=null — honest).
   * - Maps liveFacts → ChangeRecord using FACT_KIND_MAP.
   * - Sorts: dated records newest-first; null-at after, migrations (n desc) then decisions, stable.
   * - byKind: count map over all records.
   * - notConnectedFeeds: 3 feeds when liveFacts=[] (NOT_CONNECTED); empty when facts provided.
   * - Wraps with tracking() provenance.
   */
  buildTimeline(liveFacts: readonly LiveFact[] = []): ChangeTimeline {
    const ev: Evidence[] = [];

    // ── 1. Load + parse memory-intel.json ─────────────────────────────────────
    const rawArtifact = this.core.store.tryRead('memory-intel.json');

    const migrationRecords: ChangeRecord[] = [];
    const decisionRecords: ChangeRecord[] = [];

    if (rawArtifact === null) {
      ev.push(notConnected('memory-intel.json', 'graphify-out/memory-intel.json (run pnpm graph:memory)'));
    } else {
      const parsed = MemoryIntelSchema.safeParse(rawArtifact);
      if (!parsed.success) {
        ev.push(
          evidence(
            'artifact-field',
            'memory-intel.json',
            'unexpected shape — zod parse failed; timeline has no structural history (not fabricated)',
            'graphify-out/memory-intel.json',
          ),
        );
      } else {
        const data = parsed.data;

        // ── 1a. Migrations ───────────────────────────────────────────────────
        const migrations: RawMigration[] = data.migrations ?? [];
        // Sort by n DESC for the output ordering (highest migration first).
        const sortedMigrations = [...migrations].sort((a, b) => b.n - a.n);
        for (const m of sortedMigrations) {
          const subject = m.file ?? `migration-${m.n}`;
          const detail = [m.name, m.type].filter(Boolean).join(' / ') || `migration ${m.n}`;
          const rec: ChangeRecord = {
            id: `migration-${m.n}`,
            kind: 'migration',
            action: 'applied',
            subject,
            at: null, // migrations carry no timestamps — honest null, never fabricated
            detail,
            source: 'graphify-out/memory-intel.json',
            connection: 'CONNECTED',
            evidence: [
              evidence(
                'migration',
                `migration-${m.n}`,
                detail,
                'graphify-out/memory-intel.json',
              ),
            ],
          };
          migrationRecords.push(rec);
        }
        ev.push(
          evidence(
            'artifact-field',
            'memory-intel.json:migrations',
            `${migrations.length} migrations loaded, ordered by n DESC`,
            'graphify-out/memory-intel.json',
          ),
        );

        // ── 1b. Decisions ────────────────────────────────────────────────────
        const decisions: RawDecision[] = data.decisions ?? [];
        const cappedDecisions = decisions.slice(0, DECISION_CAP);
        const wasCapped = decisions.length > DECISION_CAP;
        for (const d of cappedDecisions) {
          const subject = d.source ?? d.id;
          const detail = [d.section, d.rule].filter(Boolean).join(': ') || d.id;
          const rec: ChangeRecord = {
            id: `decision-${d.id}`,
            kind: 'decision',
            action: 'observed',
            subject,
            at: null, // decisions carry no reliable timestamps — honest null
            detail,
            source: 'graphify-out/memory-intel.json',
            connection: 'CONNECTED',
            evidence: [
              evidence(
                'decision',
                d.id,
                detail,
                'graphify-out/memory-intel.json',
              ),
            ],
          };
          decisionRecords.push(rec);
        }
        ev.push(
          evidence(
            'artifact-field',
            'memory-intel.json:decisions',
            wasCapped
              ? `${decisions.length} decisions found; capped to ${DECISION_CAP} most relevant (first ${DECISION_CAP})`
              : `${decisions.length} decisions loaded`,
            'graphify-out/memory-intel.json',
          ),
        );
      }
    }

    // ── 2. Map injected live facts ─────────────────────────────────────────────
    const liveRecords: ChangeRecord[] = liveFacts.map((fact, i) => {
      const kind = factKind(fact.kind);
      return {
        id: `live-${fact.adapter}-${fact.kind}-${i}`,
        kind,
        action: 'observed',
        subject: fact.subject,
        at: fact.at,
        detail: fact.detail,
        source: `adapter:${fact.adapter}`,
        connection: 'CONNECTED',
        evidence: [...fact.evidence],
      } satisfies ChangeRecord;
    });

    if (liveFacts.length > 0) {
      ev.push(
        evidence(
          'artifact-field',
          'live-facts',
          `${liveFacts.length} live fact(s) injected from adapters`,
          'adapter(s)',
        ),
      );
    }

    // ── 3. Sort ────────────────────────────────────────────────────────────────
    // Partition into dated (at !== null) and null-at groups.
    const allRecords: ChangeRecord[] = [...liveRecords, ...migrationRecords, ...decisionRecords];

    // Live records may have dates; migration + decision records are all null-at.
    const dated = allRecords.filter((r) => r.at !== null);
    const nullAt = allRecords.filter((r) => r.at === null);

    // Dated records: newest-first (ISO sort descending, stable).
    dated.sort((a, b) => {
      const cmp = (b.at as string).localeCompare(a.at as string);
      if (cmp !== 0) return cmp;
      return a.id.localeCompare(b.id); // stable tie-break
    });

    // Null-at: migrations first (already ordered by n DESC from construction), then decisions.
    // migrationRecords and decisionRecords are already in the right order; nullAt preserves
    // that insertion order since we spread migrations before decisions in allRecords.
    // We just need to ensure the partition preserves insertion order (filter is stable in JS).

    const records: readonly ChangeRecord[] = [...dated, ...nullAt];

    // ── 4. byKind counts ───────────────────────────────────────────────────────
    const byKind: Record<string, number> = {};
    for (const r of records) {
      byKind[r.kind] = (byKind[r.kind] ?? 0) + 1;
    }

    // ── 5. Not-connected feeds ─────────────────────────────────────────────────
    const liveConnected = liveFacts.length > 0;
    const notConnectedFeeds = liveConnected
      ? []
      : NOT_CONNECTED_FEEDS.map((f) => ({ feed: f.feed, source: f.source }));

    if (!liveConnected) {
      for (const feed of NOT_CONNECTED_FEEDS) {
        ev.push(notConnected(feed.feed, feed.source));
      }
    }

    // ── 6. Summary ─────────────────────────────────────────────────────────────
    const kindList = Object.entries(byKind)
      .map(([k, n]) => `${n} ${k}`)
      .join(', ');
    const honestyNote = liveConnected
      ? `${liveFacts.length} live fact(s) included.`
      : `Live change feeds NOT CONNECTED — structural history only (migrations + decisions from graphify-out/memory-intel.json). Wire the GitHub, GitHub Actions, and Vercel adapters for live commit/PR/deploy events.`;
    const summary =
      `Timeline: ${records.length} record(s) (${kindList || 'none'}). ` +
      honestyNote;

    // ── 7. Wrap with tracking() ────────────────────────────────────────────────
    return tracking(
      {
        records,
        byKind,
        notConnectedFeeds,
        summary,
      },
      {
        evidence: ev,
        liveConnected,
        now: this.now,
      },
    );
  }
}
